import sys


def _skip_ws(s, i, n):
    while i < n:
        c = s[i]
        if c == ' ' or c == '\t' or c == '\n' or c == '\r':
            i += 1
        else:
            break
    return i


def _parse_hex4(s, i, n):
    if i + 4 > n:
        raise ValueError
    x = 0
    for k in range(i, i + 4):
        c = s[k]
        if '0' <= c <= '9':
            x = (x << 4) | (ord(c) - 48)
        elif 'a' <= c <= 'f':
            x = (x << 4) | (ord(c) - 87)
        elif 'A' <= c <= 'F':
            x = (x << 4) | (ord(c) - 55)
        else:
            raise ValueError
    return x


def _parse_string(s, n, i):
    if i >= n or s[i] != '"':
        raise ValueError

    i += 1
    start = i
    parts = []

    while i < n:
        c = s[i]

        if c == '"':
            if parts:
                if i > start:
                    parts.append(s[start:i])
                return ''.join(parts), i + 1
            return s[start:i], i + 1

        if c == '\\':
            if i > start:
                parts.append(s[start:i])

            i += 1
            if i >= n:
                raise ValueError

            esc = s[i]

            if esc == '"':
                parts.append('"')
                i += 1
                start = i
            elif esc == '\\':
                parts.append('\\')
                i += 1
                start = i
            elif esc == '/':
                parts.append('/')
                i += 1
                start = i
            elif esc == 'b':
                parts.append('\b')
                i += 1
                start = i
            elif esc == 'f':
                parts.append('\f')
                i += 1
                start = i
            elif esc == 'n':
                parts.append('\n')
                i += 1
                start = i
            elif esc == 'r':
                parts.append('\r')
                i += 1
                start = i
            elif esc == 't':
                parts.append('\t')
                i += 1
                start = i
            elif esc == 'u':
                j = i + 1
                cp = _parse_hex4(s, j, n)
                p = j + 4

                if 0xD800 <= cp <= 0xDBFF:
                    if p + 6 <= n and s[p] == '\\' and s[p + 1] == 'u':
                        low = _parse_hex4(s, p + 2, n)
                        if 0xDC00 <= low <= 0xDFFF:
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00)
                            parts.append(chr(cp))
                            i = p + 6
                            start = i
                            continue
                    raise ValueError

                if 0xDC00 <= cp <= 0xDFFF:
                    raise ValueError

                parts.append(chr(cp))
                i = p
                start = i
            else:
                raise ValueError

        elif c < '\x20':
            raise ValueError
        else:
            i += 1

    raise ValueError


def _parse_number(s, n, i):
    start = i

    if i < n and s[i] == '-':
        i += 1

    if i >= n:
        raise ValueError

    c = s[i]
    if c == '0':
        i += 1
    elif '1' <= c <= '9':
        i += 1
        while i < n and '0' <= s[i] <= '9':
            i += 1
    else:
        raise ValueError

    is_float = False

    if i < n and s[i] == '.':
        i += 1
        if i >= n or not ('0' <= s[i] <= '9'):
            raise ValueError
        while i < n and '0' <= s[i] <= '9':
            i += 1
        is_float = True

    if i < n and (s[i] == 'e' or s[i] == 'E'):
        i += 1
        if i < n and (s[i] == '+' or s[i] == '-'):
            i += 1
        if i >= n or not ('0' <= s[i] <= '9'):
            raise ValueError
        while i < n and '0' <= s[i] <= '9':
            i += 1
        is_float = True

    token = s[start:i]

    if is_float:
        try:
            v = float(token)
        except OverflowError:
            v = float('inf') if not token.startswith('-') else float('-inf')
        return v, i

    return int(token), i


def _parse_atomic(s, n, i):
    if i >= n:
        raise ValueError

    c = s[i]

    if c == '"':
        return _parse_string(s, n, i)

    if c == 't':
        if i + 4 <= n and s[i:i+4] == 'true':
            return True, i + 4
        raise ValueError

    if c == 'f':
        if i + 5 <= n and s[i:i+5] == 'false':
            return False, i + 5
        raise ValueError

    if c == 'n':
        if i + 4 <= n and s[i:i+4] == 'null':
            return None, i + 4
        raise ValueError

    if c == '-' or ('0' <= c <= '9'):
        return _parse_number(s, n, i)

    raise ValueError


def _finish_value(val, stack):
    top = stack[-1]

    if top[0] == '[':
        top[1].append(val)
        top[3] = 'sep'
        return 'array_sep'

    key = top[2]
    d = top[1]

    if key in d:
        raise ValueError

    d[key] = val
    top[3] = 'sep'
    return 'object_sep'


def parse_json(text: str) -> object:
    try:
        sys.set_int_max_str_digits(0)
    except Exception:
        pass

    s = text
    n = len(s)
    i = 0
    stack = []
    mode = 'value'
    result = None

    while True:
        i = _skip_ws(s, i, n)

        if mode == 'done':
            break

        if i >= n:
            raise ValueError

        if mode == 'value':
            if stack:
                top = stack[-1]

                if top[0] == '[' and top[3] == 'open' and s[i] == ']':
                    val = top[1]
                    stack.pop()
                    i += 1

                    if not stack:
                        result = val
                        mode = 'done'
                    else:
                        mode = _finish_value(val, stack)
                    continue

                if top[0] == '{' and top[3] == 'open' and s[i] == '}':
                    val = top[1]
                    stack.pop()
                    i += 1

                    if not stack:
                        result = val
                        mode = 'done'
                    else:
                        mode = _finish_value(val, stack)
                    continue

            c = s[i]

            if c == '{':
                stack.append(['{', {}, None, 'open'])
                mode = 'object_key'
                continue

            if c == '[':
                stack.append(['[', [], None, 'open'])
                mode = 'value'
                continue

            val, i = _parse_atomic(s, n, i)

            if not stack:
                result = val
                mode = 'done'
            else:
                mode = _finish_value(val, stack)
            continue

        if mode == 'object_key':
            top = stack[-1]
            c = s[i]

            if top[3] == 'open' and c == '}':
                val = top[1]
                stack.pop()
                i += 1

                if not stack:
                    result = val
                    mode = 'done'
                else:
                    mode = _finish_value(val, stack)
                continue

            if c != '"':
                raise ValueError

            key, i = _parse_string(s, n, i)
            i = _skip_ws(s, i, n)

            if i >= n or s[i] != ':':
                raise ValueError

            i += 1
            top[3] = 'value'
            top[2] = key
            mode = 'object_value'
            continue

        if mode == 'object_value':
            c = s[i]

            if c == '{':
                stack.append(['{', {}, None, 'open'])
                mode = 'object_key'
                continue

            if c == '[':
                stack.append(['[', [], None, 'open'])
                mode = 'value'
                continue

            val, i = _parse_atomic(s, n, i)

            if not stack:
                result = val
                mode = 'done'
            else:
                mode = _finish_value(val, stack)
            continue

        if mode == 'array_sep':
            top = stack[-1]
            c = s[i]

            if c == ']':
                val = top[1]
                stack.pop()
                i += 1

                if not stack:
                    result = val
                    mode = 'done'
                else:
                    mode = _finish_value(val, stack)
                continue

            if c == ',':
                i += 1
                top[3] = 'value'
                mode = 'value'
                continue

            raise ValueError

        if mode == 'object_sep':
            top = stack[-1]
            c = s[i]

            if c == '}':
                val = top[1]
                stack.pop()
                i += 1

                if not stack:
                    result = val
                    mode = 'done'
                else:
                    mode = _finish_value(val, stack)
                continue

            if c == ',':
                i += 1
                top[3] = 'key'
                mode = 'object_key'
                continue

            raise ValueError

        raise ValueError

    if i != n:
        raise ValueError

    return result
